(()=>{const assets={"door":"data:image/png;base64,","desk":"data:image/png;base64,","flush":"data:audio/mpeg;base64,"};
let side=0,last='',audio=null;window.custiaQuartersStop=()=>{if(audio){audio.pause();audio=null}};function el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}function button(text,fn){const b=el('button',text);b.type='button';b.onclick=fn;return b}window.custiaQuartersDraw=(host,r,open)=>{const id=r.uid||r.owner+'|'+r.id;if(id!==last){last=id;side=0}const root=el('section',null,'q949');host.append(root);function draw(){root.replaceChildren();const nav=el('div',null,'q949nav');nav.append(button('‹',turn),el('strong',side?'Entrance / 02':'Desk / 01'),button('›',turn));root.append(nav);const scene=el('div',null,'q949scene'),im=el('img');im.src=assets[side?'door':'desk'];im.alt=side?'Room entrance and toilet':'Room desk and poster';im.draggable=false;scene.append(im);root.append(scene);function spot(name,x,y,w,h,fn){const b=button('',fn);b.className='q949spot';b.setAttribute('aria-label',name);b.title=name;Object.assign(b.style,{left:x+'%',top:y+'%',width:w+'%',height:h+'%'});scene.append(b)}function bed(){const d=el('dialog',null,'q949dialog');d.append(el('h3','Inspect bed'),button('Pillow',()=>{d.close();open(2)}),button('Blanket',()=>{d.close();open(0)}),button('Cancel',()=>d.close()));document.body.append(d);d.onclose=()=>d.remove();d.showModal()}const edge=side?13:21;for(const x of [0,100-edge]){spot('Upper bed',x,9,edge,30,bed);spot('Lower bed',x,57,edge,28,bed);spot('Under bed',x,85,edge,15,()=>open(1))}if(side){spot('Flush toilet',14,48,17,31,()=>{if(audio&&!audio.paused)return;audio=new Audio(assets.flush);audio.play().catch(()=>{})});spot('Flush button',24,47,4,7,()=>{if(audio&&!audio.paused)return;audio=new Audio(assets.flush);audio.play().catch(()=>{})});spot('CUSTIA MAIL',64,55,12,15,()=>location.href='mail.html')}else{spot('Drawer',37,57,28,25,()=>open(3));spot('Poster',47,28,9,21,()=>open(4))}const foot=el('div',null,'q949nav');foot.append(button('Turn around ↻',turn));root.append(foot)}function turn(){window.custiaQuartersStop();side=1-side;draw()}draw()};})();